const m = $input.first().json;
const body = (m.body || '').slice(0, 4000);

const system = `Tu es l'assistant de tri de la boîte mail de l'équipe Partenariats de la Liste BDE ESSEC (association étudiante).
Ta mission : décider si un mail entrant mérite d'être traité par l'équipe.

PERTINENT (pertinent = true) :
- proposition ou réponse concernant un partenariat, sponsoring, dotation, mécénat, collaboration avec une marque ou une entreprise
- demande d'information sur le BDE, ses événements, sa liste, sa visibilité
- organisation d'un événement, d'un échange, d'un rendez-vous avec l'équipe
- tout message écrit par une vraie personne qui s'adresse au BDE

NON PERTINENT (pertinent = false) :
- newsletters, publicités, promotions de masse
- notifications automatiques (Google, réseaux sociaux, outils SaaS, factures, sécurité de compte)
- spam, phishing, arnaques
- messages sans aucun rapport avec le BDE

En cas de doute, réponds pertinent = true : il vaut mieux un ticket de trop qu'un partenaire perdu.

Réponds UNIQUEMENT avec un objet JSON, sans texte autour, au format exact :
{"pertinent": true, "categorie": "partenariat", "raison": "phrase courte en français"}
Valeurs possibles pour categorie : partenariat, sponsoring, evenement, question_bde, autre_pertinent, newsletter, publicite, notification, spam, hors_sujet.`;

const user = `Expéditeur : ${m.from_header || m.prospect_email || 'inconnu'}
Sujet : ${m.subject || '(sans sujet)'}
Corps :
${body || '(vide)'}`;

return [{
  json: {
    ...m,
    groq_body: {
      model: 'openai/gpt-oss-20b',
      reasoning_effort: 'low',
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user }
      ],
      temperature: 0.1,
      max_tokens: 1000
    }
  }
}];

const resp = $input.first().json;
const mail = $('K0 - Entrée Mail').first().json;

let result = { pertinent: true, categorie: 'non_classe', raison: 'Classification impossible, ticket créé par précaution' };

try {
  const content = resp.choices[0].message.content || '';
  const match = content.match(/\{[\s\S]*\}/);   // extrait le JSON même si le modèle ajoute du texte
  if (match) {
    const parsed = JSON.parse(match[0]);
    result = {
      pertinent: parsed.pertinent === true || parsed.pertinent === 'true',
      categorie: String(parsed.categorie || 'non_classe'),
      raison: String(parsed.raison || '')
    };
  }
} catch (e) {
  // on garde le résultat par défaut (pertinent = true)
}

return [{
  json: {
    ...result,
    prospect_email: mail.prospect_email,
    subject: mail.subject
  }
}];
